import{_ as s,C as e,o as l,c as n,E as a,a2 as o}from"./chunks/framework.DyLyN3RJ.js";const b=JSON.parse('{"title":"把计算费用算进去，并行审查还值得吗？","description":"","frontmatter":{"title":"把计算费用算进去，并行审查还值得吗？","date":"2026-11-02","column":"industry-architecture","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"在一份固定的并行审查研究中，计算费用与舍入不确定性是否改变方案选择？","summary":"对一份合成文档审查研究的汇总值进行成本敏感性计算，展示计算费用如何改变方案选择，以及舍入精度如何限制架构排名。","sources":"https://arxiv.org/html/2610.27488v1","pageClass":"runtime-v6-article","item_id":"SIG-20261102-004","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-02-sig-20261102-004-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-11-02-sig-20261102-004.md","filePath":"zh/industry/2026-11-02-sig-20261102-004.md","lastUpdated":1793633394000}'),p={name:"zh/industry/2026-11-02-sig-20261102-004.md"};function d(h,t,c,g,u,m){const i=e("ArticleCover"),r=e("ArticleTableScroll");return l(),n("div",null,[a(i,{image:"/assets/covers/daily-2026-11-02-sig-20261102-004-cover.png",kicker:"研究成果",title:"把计算费用算进去，并行审查还值得吗？",summary:"对一份合成文档审查研究的汇总值进行成本敏感性计算，展示计算费用如何改变方案选择，以及舍入精度如何限制架构排名。",version:"2026-11-02",languageHref:"/en/industry/2026-11-02-sig-20261102-004",languageLabel:"English"}),a(r,{language:"zh"}),t[0]||(t[0]=o('<h1 id="把计算费用算进去-并行审查还值得吗" tabindex="-1">把计算费用算进去，并行审查还值得吗？ <a class="header-anchor" href="#把计算费用算进去-并行审查还值得吗" aria-label="Permalink to &quot;把计算费用算进去，并行审查还值得吗？&quot;">​</a></h1><p>同一组检出率和误报率，可以导向不同的审查方案。本次内部数值实验中，采用论文标为 Haiku（俳句系列模型）5.5 的汇总值，假设缺陷占比为 2%、一次漏检的代价为一次误报的 20 倍：不计计算费用时，三次完整审查中任一次报警即标记的方案成本最低；加入特定的计算费用后，最低成本方案变成单次审查。模型名称沿用来源。[2]</p><p>这不是一次模型能力反转。输入的检出率没有变化，变化的是决策者愿意为它支付的资源代价。本文的核心判断是：审查设计要把漏检、误报和资源费用放在同一个有单位的比较中；用舍入汇总值做出的选择只能是条件性判断，不能升级为某种协作架构普遍更好的结论。</p><h2 id="先弄清-分工-究竟改变了什么" tabindex="-1">先弄清“分工”究竟改变了什么 <a class="header-anchor" href="#先弄清-分工-究竟改变了什么" aria-label="Permalink to &quot;先弄清“分工”究竟改变了什么&quot;">​</a></h2><p>Pei Liu（论文作者）的预印本比较了一种很窄的并行拆分：单次调用检查六项要求，三次分工调用各检查两项，且都读取完整文档。它没有工具调用、成员通信、协调者或后续过滤。另有补足未分配要求信息的分工方案，以及三次重复完整审查后按多数或任一次报警合并的方案。[1，第 3.3 节]</p><p>论文描述的材料是 300 份程序生成、约 1,100 词的信贷备忘录，每份六项检查，共 1,800 个检查单元，其中 1,136 个无缺陷。测试对象是内部可核对的不一致，不涵盖外部事实、信息遗漏或真实信贷判断。作者报告，分工可以提高部分模型的检出率，也增加误报；等调用次数并不等于等计算量。来源中的部分重复调用比较还改变了采样温度，不能把所有差异归因于责任拆分。[1，第 3—4 节]</p><p>因此，我们比较的是五种已披露选项的条件成本，不是整个多智能体架构空间。对原论文评测结果的引用仍是来源陈述，并非本次独立复现。</p><h2 id="给漏检、误报和计算量统一单位" tabindex="-1">给漏检、误报和计算量统一单位 <a class="header-anchor" href="#给漏检、误报和计算量统一单位" aria-label="Permalink to &quot;给漏检、误报和计算量统一单位&quot;">​</a></h2><p>同日完成的内部实验沿用论文表 2 的 20 行汇总值，覆盖四个来源所列模型、每个模型五种方案。记缺陷单元占比为 p，检出率为 H（检出率变量），无缺陷单元上的误报率为 F（误报率变量），一次漏检相对一次误报的成本为 r。K（相对词元量）表示相对单次审查的词元用量；词元是模型处理文本的计量单位。再令 c 表示消耗一份单次审查词元预算的假设费用，以“一次误报的成本”为单位。[2]</p><p>每份六项检查文档的条件期望成本为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>6 × [p × (1 − H) × r + (1 − p) × F] + c × K</span></span></code></pre></div><p>前半部分是六个检查单元的预期错误成本，后半部分是一整份文档的资源费用。不能把 c 当成每词元价格，也不能再给资源项乘六。它没有采用实际服务价格，更不是货币收益测算。公式假设错误代价线性可加，并把原研究检出率与误报率迁移到假设缺陷占比；这种迁移未经真实部署验证。</p><p>实验网格使用五种缺陷占比：0.001、0.01、0.02、0.05、0.37；漏检相对代价取整数 1—200；c 取 0、0.01、0.1、0.5、1、2、5、10。四个模型合计 32,000 个情景。最低成本只表示在该网格点、同一模型的五个选项中最低，不代表连续参数空间的全局最优。[2]</p><h2 id="一个选择反转-两个不能直接相减的数" tabindex="-1">一个选择反转，两个不能直接相减的数 <a class="header-anchor" href="#一个选择反转-两个不能直接相减的数" aria-label="Permalink to &quot;一个选择反转，两个不能直接相减的数&quot;">​</a></h2><p>下面仅列出开头实例所需的来源输入。它们是论文报告并舍入后的值，不是本次重新测出的性能。[1，表 2；2]</p><table tabindex="0"><thead><tr><th>方案</th><th style="text-align:right;">检出率 H</th><th style="text-align:right;">误报率 F</th><th style="text-align:right;">相对词元量 K</th></tr></thead><tbody><tr><td>单次完整审查</td><td style="text-align:right;">0.825</td><td style="text-align:right;">0.013</td><td style="text-align:right;">1.00</td></tr><tr><td>三次完整审查，任一次报警即标记</td><td style="text-align:right;">0.929</td><td style="text-align:right;">0.029</td><td style="text-align:right;">3.00</td></tr></tbody></table><p>在 p=0.02、r=20、c=0 时，内部计算得到三次任一报警方案成本最低，为每份文档 0.34092 个误报成本单位。把 c 改为 0.1 后，五种方案中单次审查成本最低，为 0.59644。两个数字来自不同费用假设，不能相减后宣称“节省了多少”；实际支出也没有在这里被测量。[2]</p><p>这两次最低成本比较，在固定 K 的情况下，都经受住了 H、F 各自正负 0.0005 的不利舍入扰动。其意义仅是：该例的选择变化不依赖显示到小数点后三位的最后一位。它没有提供置信区间，也没有覆盖词元量舍入、样本误差或重复运行波动。</p><h2 id="一个很小的最优差距为什么不能承载大结论" tabindex="-1">一个很小的最优差距为什么不能承载大结论 <a class="header-anchor" href="#一个很小的最优差距为什么不能承载大结论" aria-label="Permalink to &quot;一个很小的最优差距为什么不能承载大结论&quot;">​</a></h2><p>在缺陷占比固定为 0.02 的子网格里，正计算费用下的 5,600 次比较中，原始分工方案没有成为最低成本选项。费用为零的 800 次比较却出现了一次分工最优：来源标为 Qwen3.5（通义千问系列）9B（九十亿参数版本）的行，在 r=39 时，成本为 2.74308，比第二名“三次多数表决”低 0.0036。[2]</p><p>这个孤立的最优点未通过检出率与误报率的舍入敏感性检查。严格照舍入表值计算，无法复现“零费用也完全没有分工最优点”的控制结论；但这也不足以推翻来源的未舍入测量。实验记录保留了这一差异。32,000 个情景的完整网格在其他缺陷占比下也存在少量分工最优点，因此不能把 0.02 子网格的结果扩写为所有条件下分工都不划算。[2]</p><p>这里需要同时拒绝两个跳跃：一个舍入敏感的窄胜不等于可靠优势，一片网格中的未获胜也不等于在所有任务、价格和参数下都不可能获胜。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文区分三层材料。来源陈述是作者报告的设计和性能；内部实验依据是本研究中心对这些汇总值所做的计算；研究解释是从计算中得到的选择方法。内部实验的算术由另一份程序以十进制方法核对，仍属于同一生产体系的内部验证，没有变成第三方独立证据。[2]</p><p>[1] Pei Liu，《越多越好吗？金融审查任务中单体与多体语言模型设置的比较》（原题：The More the Better? A Comparison of Single- and Multi-Agent LLM Setups on a Financial Review Task），arXiv（开放预印本平台），研究预印本 v1，2026-10-20。设计见第 3 节，输入见表 2，结果与限制见第 4—5 节及附录。<a href="https://arxiv.org/html/2610.27488v1" target="_blank" rel="noreferrer">阅读固定版本</a>。版本公开只建立可追溯来源，不建立理论有效性或独立复现；引用也不构成背书。</p><p>[2] 研究中心，2026-11-02 同日内部实验 EXP004（成本敏感性实验）：20 行输入、32,000 情景完整网格、结果、执行记录及十进制核对记录。候选附带的<a href="/joinwell52/assets/evidence/2026-11-02-sig-20261102-004/index.json">可复核证据包</a>保留这些同运行制品。本文未重新调用模型，也未重跑原始文档评测；文章生产仅整理已经完成的研究。</p><p>封面是依据本次成本选择关系生成的编辑概念图，不是数据图或实际系统截图。正文公式与表格已足以承载精确关系，不另配装饰性解释图。</p><h2 id="部署前仍缺哪些测量" tabindex="-1">部署前仍缺哪些测量 <a class="header-anchor" href="#部署前仍缺哪些测量" aria-label="Permalink to &quot;部署前仍缺哪些测量&quot;">​</a></h2><p>原研究没有在已核验材料中提供可下载的完整生成器、文档、标签和预测包，因此本次不能忠实重跑它的 300 份文档评测。来源报告的提示词和指令依赖、单一要求划分、分工方案缺少整轮重复运行，都限制了结果迁移。按检查单元计分的误报也可能包含“错误归类到另一项要求”的报警；如果真实处理按整份文件裁决，人工成本关系会变，本文未重算这套评分。[1—2]</p><p>对准备采用并行审查的工程团队，当前可用的是一个有边界的决策方法：先声明缺陷基率、错误代价和资源单位，再在相同条件下比较分工与重复完整审查。真实缺陷率是多少？人工处理一条误报是否具有固定成本？统一温度、改变分工和重复运行后，选择边界还能保留吗？在这些问题有现场证据之前，本实验不能给出产品收益、金融部署建议或通用架构排名。</p>',30))])}const x=s(p,[["render",d]]);export{b as __pageData,x as default};
